cd /workspace; python - <<'EOF'
import sqlite3
con=sqlite3.connect('file:data/warehouse.db?mode=ro',uri=True)
for (n,s) in con.execute("select name,sql from sqlite_master"):
    print(s); 
    if s and 'TABLE' in s: 
        print(con.execute(f"select count(*) from {n}").fetchone())
        for r in con.execute(f"select * from {n} limit 3"): print(r)
for r in con.execute("select * from warehouse_sync_log"): print(r)
EOF

